/**
 * Ported unchanged from phriend-api-nestjs src/autopilot/contact-detect.ts (the shared rules: the API runs them on
 * listings and messages, the apps may run them to warn before sending).
 *
 * Contact details in what a provider writes (SPEC 10.5, off-platform contact; product intent: clients and providers talk
 * and pay through Phriend). Deterministic and free, so it runs on every listing before any AI pass: emails (also "at /
 * dot" spellings), links and bare domains, PH mobile and landline numbers (+63, 63, 09xx, spaced, dashed, digit
 * look-alikes, spelled out in English or Filipino), foreign numbers, social handles named with their app, account
 * numbers after a bank or wallet name. Pure: no I/O.
 *
 * A **sure** hit is a way to reach the provider outside Phriend (the autopilot hides it). A **weak** hit could be one
 * (a bare @name, "message me on Viber" without an id, an 8-digit number without an area code, a long run of digits):
 * Ops decides. Prices, times, years, addresses, licence numbers and a payment method named without a number
 * ("GCash accepted") are not hits.
 */
import { asciiDigits } from "./digits";

export type ContactKind = "email" | "url" | "phone" | "handle" | "payment_number" | "app_invite";

export interface ContactHit {
  kind: ContactKind;
  /** the matched text, as written (from the original string) */
  text: string;
  /** offsets in the original string */
  start: number;
  end: number;
  sure: boolean;
}

/** What a hidden detail is replaced with in the listing. */
export const CONTACT_MARK = "[removed]";

// ---- normalising (positions are mapped back to the original text) ----

/** zero-width, joiner, bidi and filler characters someone may slip between digits or letters (code point ranges) */
const INVISIBLE: readonly [number, number][] = [
  [0x00ad, 0x00ad],
  [0x034f, 0x034f],
  [0x061c, 0x061c],
  [0x115f, 0x1160],
  [0x17b4, 0x17b5],
  [0x180b, 0x180f],
  [0x200b, 0x200f],
  [0x202a, 0x202e],
  [0x2060, 0x206f],
  [0x2800, 0x2800],
  [0x3164, 0x3164],
  [0xfe00, 0xfe0f],
  [0xfeff, 0xfeff],
  [0xffa0, 0xffa0],
  [0xfff9, 0xfffb],
  [0x1d173, 0x1d17a],
  [0xe0000, 0xe007f],
  [0xe0100, 0xe01ef],
];
const invisible = (cp: number) => INVISIBLE.some(([a, b]) => cp >= a && cp <= b);

interface Normalized {
  text: string;
  /** for each UTF-16 unit of `text`, the index in the original where its character starts */
  at: number[];
}

/** NFKC per character (full-width forms, ligatures), any decimal digit as ASCII, invisible characters dropped. */
function normalize(raw: string): Normalized {
  let text = "";
  const at: number[] = [];
  for (let i = 0; i < raw.length; ) {
    const cp = raw.codePointAt(i)!;
    const ch = String.fromCodePoint(cp);
    if (!invisible(cp)) {
      const n = asciiDigits(ch.normalize("NFKC"));
      for (let k = 0; k < n.length; k++) at.push(i);
      text += n;
    }
    i += ch.length;
  }
  return { text, at };
}

// ---- patterns (run on the normalised text) ----

/** what may sit between the digits of one number: spaces, dots, commas, underscores, dashes, brackets (at most 3 in a
 * row); not ":" or "/", so times and dates never join into a number */
const SEP = String.raw`[\s.,_\-‐-―()]{0,3}`;
/** a digit, or a letter that stands for one (o/O for 0, l/I for 1) when no letter follows it */
const DIG = String.raw`(?:\d|[oOlI](?!\p{L}))`;
const NOT_BEFORE = String.raw`(?<![\p{L}\p{N}])`;
const NO_MORE_DIGITS = String.raw`(?![\s.\-]?\d)`;

const EMAIL = /(?<![\p{L}\p{N}._%+-])[\p{L}\p{N}._%+-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)*\.\p{L}{2,}/gu;
const EMAIL_SPELLED = new RegExp(
  String.raw`(?<![\p{L}\p{N}._+-])[\p{L}\p{N}._+-]{2,}\s*[\[({]?\s*(?:at|@)\s*[\])}]?\s*(?:gmail|yahoo|ymail|outlook|hotmail|live|icloud|proton(?:mail)?|aol|zoho)\s*[\[({]?\s*(?:dot|\.)\s*[\])}]?\s*(?:com|ph|net)(?![\p{L}\p{N}])`,
  "giu",
);
const URL_SCHEME = /(?:\b(?:https?|ftp):\/\/|\bwww\.)[^\s<>"'`]+/giu;
/** short links and chat links: their TLDs (me, ly, gl, ee) are too common in prose to match bare */
const SHORT_LINK = /(?<![\p{L}\p{N}@._-])(?:t\.me|wa\.me|m\.me|fb\.me|fb\.com|bit\.ly|goo\.gl|ow\.ly|cutt\.ly|linktr\.ee|is\.gd|rb\.gy|shorturl\.at|tinyurl\.com)(?:\/[^\s<>"'`]*)?/giu;
const BARE_DOMAIN =
  /(?<![\p{L}\p{N}@._-])((?:[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?\.)+)(com|net|org|ph|io|app|dev|info|biz|xyz|shop|store|site|online|link|page|asia)(\.[a-z]{2})?(?![\p{L}\p{N}-])(?:\/[^\s<>"'`]*)?/giu;
/** TLDs that are also words ("home.page", "cleaning.shop" with a space missing): a bare domain on them is only weak */
const WORD_TLDS = new Set(["app", "info", "shop", "store", "site", "online", "link", "page"]);
/** our own pages are not an outside contact */
const OWN_DOMAIN = /^(?:https?:\/\/)?(?:[\w-]+\.)*phriend\.app(?:[/?#]|$)/i;

const MOBILE = new RegExp(String.raw`(?:(?<!\p{N})(?:\(\s?)?\+\s?6\s?3|(?<!\p{N})6\s?3|(?<!\p{N})0|${NOT_BEFORE}[oO])${SEP}9(?:${SEP}${DIG}){9}${NO_MORE_DIGITS}`, "gu");
const MOBILE_NO_PREFIX = new RegExp(String.raw`${NOT_BEFORE}9\d{2}${SEP}\d{3}${SEP}\d{4}${NO_MORE_DIGITS}`, "gu");
/** words that make an unprefixed 9xx xxx xxxx a phone number */
const PHONE_CUE = /(?:call|text|txt|sms|cp|cell|mobile|phone|tel|contact|number|num|no\.?|globe|smart|tnt|tm|sun|dito|viber|whats\s?app|telegram|gcash|maya|tawag|i-?text|#)\W{0,4}$/iu;
const LANDLINE = new RegExp(String.raw`${NOT_BEFORE}\(?0(?:2|[3-8]\d)\)?${SEP}[2-9]\d{2,3}${SEP}\d{4}${NO_MORE_DIGITS}`, "gu");
const INTERNATIONAL = new RegExp(String.raw`(?<![\p{L}\p{N}+])\+\s?\d(?:${SEP}\d){7,13}${NO_MORE_DIGITS}`, "gu");
/** Metro Manila's 8-digit numbers without the (02): could be one */
const METRO_8 = new RegExp(String.raw`(?<![\p{L}\p{N}.,#])8\d{3}[\s.\-]?\d{4}${NO_MORE_DIGITS}`, "gu");
/** 10 or more digits in one run: not a price (₱1,000,000 has 7), maybe a number */
const LONG_DIGITS = new RegExp(String.raw`(?<![\p{L}\p{N}.,#])\d(?:[\s.\-]?\d){9,}${NO_MORE_DIGITS}`, "gu");

const NUMBER_WORD = String.raw`(?:zero|oh|one|two|three|four|five|six|seven|eight|nine|sero|isa|dalawa|tatlo|apat|lima|anim|pito|walo|siyam)`;
const SPELLED = new RegExp(String.raw`(?<![\p{L}\p{N}])(?:${NUMBER_WORD}|\d+)(?:[\s,.\-]+(?:${NUMBER_WORD}|\d+)){6,}(?![\p{L}\p{N}])`, "giu");
const NUMBER_WORD_ONLY = new RegExp(String.raw`^${NUMBER_WORD}$`, "iu");

/** apps a provider would move a client to; "line", "signal" and "messenger" (a courier) are ordinary words, left out */
const APP = String.raw`(?:telegram|viber|whats\s?app|wechat|we\s?chat|instagram|insta|ig|facebook|fb|tiktok|tik\s?tok|kakao(?:\s?talk)?|snapchat|twitter|discord|skype|line\s?(?:app|id)|signal\s?app)`;
/** "IG: juan.shoots", "Telegram @fixitph", "Viber ID is juanfix", "fb - juan.dc" */
const APP_HANDLE = new RegExp(
  String.raw`(?<![\p{L}\p{N}])${APP}(?![\p{L}])\s*(?:(id|name|account|acct|page|handle|user(?:name)?)\s*)?(?:[:=\-–]\s*|\b(?:is|ay)\s+|(?=@))@?([\p{L}\p{N}_.]{3,40})`,
  "giu",
);
/** "add me on Viber", "PM me sa FB", "i-message mo ako sa Telegram" */
const APP_INVITE = new RegExp(
  String.raw`(?<![\p{L}])(?:add|message|msg|pm|dm|chat|contact|text|call|reach|follow|hmu|find|search|hanapin|i-?add|i-?message|i-?pm|i-?chat|i-?text|i-?follow|mag-?message|mag-?pm)\b[^.\n!?]{0,25}?(?<![\p{L}])${APP}(?![\p{L}])`,
  "giu",
);
const BARE_HANDLE = /(?<![\p{L}\p{N}._%+-])@([A-Za-z_][A-Za-z0-9_.]{2,29})(?![A-Za-z0-9_@])/gu;
/** an account number after a bank or wallet name (a wallet or bank named without one is fine) */
const PAYMENT_NUMBER = new RegExp(
  String.raw`(?<![\p{L}])(?:gcash|g-cash|maya|paymaya|coins\.ph|bdo|bpi|metrobank|landbank|unionbank|security\s?bank|rcbc|chinabank|pnb|eastwest|bank|acct|account)(?![\p{L}])[^\n\d]{0,30}?(\d(?:[\s.\-]?\d){7,})${NO_MORE_DIGITS}`,
  "giu",
);
/** words after "app:" that are not a handle */
const NOT_A_HANDLE = new Set(["none", "wala", "only", "available", "accepted", "ok", "okay", "yes", "also", "same", "please", "lang", "lamang", "ang", "mga", "the", "and", "not", "chat", "call", "message", "inside", "app", "phriend"]);
/** "no Viber", "walang Telegram": a rule against the app, not an invitation */
const NEGATED = /(?:\b(?:no|not|never|without|walang|bawal|hindi)\s+(?:\p{L}+\s+){0,2})$/iu;

interface RawHit {
  kind: ContactKind;
  start: number;
  end: number;
  sure: boolean;
}

/** the order a tie on the same span is broken in */
const PRIORITY: Record<ContactKind, number> = { email: 0, url: 1, phone: 2, handle: 3, payment_number: 4, app_invite: 5 };

function* matches(re: RegExp, text: string): Generator<RegExpExecArray> {
  re.lastIndex = 0;
  for (let m = re.exec(text); m; m = re.exec(text)) {
    yield m;
    if (m[0] === "") re.lastIndex++;
  }
}

const trimUrl = (s: string) => s.replace(/[.,;:!?)\]}'"]+$/u, "");

function collect(text: string): RawHit[] {
  const hits: RawHit[] = [];
  const add = (kind: ContactKind, start: number, end: number, sure: boolean) => {
    if (end > start) hits.push({ kind, start, end, sure });
  };
  const negated = (start: number) => NEGATED.test(text.slice(Math.max(0, start - 24), start));

  for (const m of matches(EMAIL, text)) add("email", m.index, m.index + m[0].length, true);
  for (const m of matches(EMAIL_SPELLED, text)) add("email", m.index, m.index + m[0].length, true);
  for (const re of [URL_SCHEME, SHORT_LINK]) {
    for (const m of matches(re, text)) {
      const url = trimUrl(m[0]);
      if (!OWN_DOMAIN.test(url)) add("url", m.index, m.index + url.length, true);
    }
  }
  for (const m of matches(BARE_DOMAIN, text)) {
    const [, labels, tld, cc] = m as unknown as [string, string, string, string | undefined];
    // a capital TLD ("St.Peter.Org", "cleaning.Shop") is a sentence with a space missing; so is a number ("2.0.app")
    if (tld !== tld.toLowerCase() || (cc && cc !== cc.toLowerCase())) continue;
    if (labels.split(".").some((l) => /^\d+$/.test(l))) continue;
    const url = trimUrl(m[0]);
    if (!OWN_DOMAIN.test(url)) add("url", m.index, m.index + url.length, !WORD_TLDS.has(tld) || /[/]/.test(url));
  }
  for (const re of [MOBILE, LANDLINE, INTERNATIONAL]) {
    for (const m of matches(re, text)) add("phone", m.index, m.index + m[0].length, true);
  }
  for (const m of matches(MOBILE_NO_PREFIX, text)) add("phone", m.index, m.index + m[0].length, PHONE_CUE.test(text.slice(Math.max(0, m.index - 24), m.index)));
  for (const m of matches(SPELLED, text)) {
    const tokens = m[0].split(/[\s,.-]+/u).filter(Boolean);
    const words = tokens.filter((t) => NUMBER_WORD_ONLY.test(t)).length;
    const digits = tokens.reduce((n, t) => n + (NUMBER_WORD_ONLY.test(t) ? 1 : t.length), 0);
    if (words >= 2 && digits >= 7) add("phone", m.index, m.index + m[0].length, digits >= 10);
  }
  for (const m of matches(METRO_8, text)) add("phone", m.index, m.index + m[0].length, false);
  for (const m of matches(LONG_DIGITS, text)) {
    // a list of small or repeated numbers ("ages 18 19 20 21 22", "5000 5000 5000") is not a number
    const groups = m[0].split(/[\s.-]+/u);
    if (groups.length >= 3 && (new Set(groups).size === 1 || groups.every((g) => g.length <= 2))) continue;
    add("phone", m.index, m.index + m[0].length, false);
  }
  for (const m of matches(PAYMENT_NUMBER, text)) {
    const digits = m[1]!;
    const start = m.index + m[0].length - digits.length;
    add("payment_number", start, start + digits.length, true);
  }
  for (const m of matches(APP_HANDLE, text)) {
    const id = m[2]!;
    // an id with a digit, dot or underscore, after "@" or after "ID"/"username": a handle; a plain word ("IG: juanshoots")
    // could be one; nothing at all after a "no Viber"
    const marked = /[\d._]/u.test(id) || m[0].includes("@") || m[1] !== undefined;
    if (!marked) {
      // "viber: yes", "telegram is great", "fb - ang bait": only "app: word" can be a handle, never a common word
      const colon = /[:=]/u.test(m[0].slice(0, m[0].length - id.length));
      if (!colon || negated(m.index) || NOT_A_HANDLE.has(id.toLowerCase()) || id.length < 4) continue;
    }
    add("handle", m.index, m.index + m[0].length, marked);
  }
  for (const m of matches(APP_INVITE, text)) add("app_invite", m.index, m.index + m[0].length, false);
  for (const m of matches(BARE_HANDLE, text)) add("handle", m.index, m.index + m[0].length, false);
  return hits;
}

/** Overlapping hits: a sure one beats a weak one, then the longer, then the earlier, then by kind. */
function resolve(hits: RawHit[]): RawHit[] {
  const ranked = [...hits].sort((a, b) => Number(b.sure) - Number(a.sure) || b.end - b.start - (a.end - a.start) || a.start - b.start || PRIORITY[a.kind] - PRIORITY[b.kind]);
  const kept: RawHit[] = [];
  for (const h of ranked) if (!kept.some((k) => h.start < k.end && k.start < h.end)) kept.push(h);
  return kept.sort((a, b) => a.start - b.start);
}

/** The contact details in `text`, in order, each once. Empty when there are none. */
export function findContacts(raw: string | null | undefined): ContactHit[] {
  if (!raw) return [];
  const n = normalize(raw);
  const origin = (i: number) => (i < n.at.length ? n.at[i]! : raw.length);
  return resolve(collect(n.text)).map((h) => {
    const start = origin(h.start);
    const end = origin(h.end);
    return { kind: h.kind, text: raw.slice(start, end), start, end, sure: h.sure };
  });
}

/**
 * `text` with each hit replaced by CONTACT_MARK; everything else is kept exactly. When the marks would take the text over
 * `maxLength`, the details are dropped instead (and the spaces around them closed up).
 */
export function redactContacts(text: string, hits: readonly Pick<ContactHit, "start" | "end">[], maxLength = Infinity): string {
  if (!hits.length) return text;
  const replace = (mark: string) => {
    let out = "";
    let last = 0;
    for (const h of [...hits].sort((a, b) => a.start - b.start)) {
      if (h.start < last) continue;
      out += text.slice(last, h.start) + mark;
      last = h.end;
    }
    return out + text.slice(last);
  };
  const marked = replace(CONTACT_MARK);
  if (marked.length <= maxLength) return marked;
  const dropped = replace("")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/[ \t]+([.,;:!?])/g, "$1")
    .trim();
  return dropped || CONTACT_MARK; // a field that was only a detail keeps the mark rather than going empty
}
